import{_ as l,o as t,c as o,ah as a}from"./chunks/framework.DjU4PSOm.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. 후설 비판 — 휠레 비판","slug":"_1-후설-비판-—-휠레-비판","link":"#_1-후설-비판-—-휠레-비판","children":[]},{"level":2,"title":"2. 즉자와 대자","slug":"_2-즉자와-대자","link":"#_2-즉자와-대자","children":[]},{"level":2,"title":"3. 무와 무화","slug":"_3-무와-무화","link":"#_3-무와-무화","children":[]},{"level":2,"title":"4. 타자와 시선","slug":"_4-타자와-시선","link":"#_4-타자와-시선","children":[]},{"level":2,"title":"5. 자유와 불안","slug":"_5-자유와-불안","link":"#_5-자유와-불안","children":[]}],"relativePath":"philosophy/Phenomenology/05. 사르트르.md","filePath":"philosophy/Phenomenology/05. 사르트르.md"}'),r={name:"philosophy/Phenomenology/05. 사르트르.md"};function n(i,e,s,_,p,h){return t(),o("div",null,[...e[0]||(e[0]=[a('<h2 id="_1-후설-비판-—-휠레-비판" tabindex="-1">1. 후설 비판 — 휠레 비판 <a class="header-anchor" href="#_1-후설-비판-—-휠레-비판" aria-label="Permalink to &quot;1. 후설 비판 — 휠레 비판&quot;">​</a></h2><p>의식은 철저하게 지향적이며, 의식에 지향적이지 않은 부분은 없음. 감각적 현상(감각 자료, 휠레)은 의식이 아니라 대상에 속함. (내 머릿속에 뭐가 있는 게 아니라, 그냥 거기 있는 것을 보는 것)</p><p>의식은 자기 자신에 대해 항상 선반성적으로 관계함.</p><h2 id="_2-즉자와-대자" tabindex="-1">2. 즉자와 대자 <a class="header-anchor" href="#_2-즉자와-대자" aria-label="Permalink to &quot;2. 즉자와 대자&quot;">​</a></h2><p><strong>즉자 존재</strong>: 있는 그대로 있음. 자신으로 존재함 — 대상(의식이 아닌 것)의 존재방식.</p><p><strong>대자 존재</strong>: 있는 그대로 있지 않음. 자신이 아닌 것으로 존재함 — 의식의 존재방식.</p><p>반성에서 나타나는 자아는 대자가 아니라 즉자임 — 자아는 하나의 초월적 즉자.</p><h2 id="_3-무와-무화" tabindex="-1">3. 무와 무화 <a class="header-anchor" href="#_3-무와-무화" aria-label="Permalink to &quot;3. 무와 무화&quot;">​</a></h2><p>무는 부정판단에서 발생하는 것이 아니라 세계에서 직접적으로 발견됨. 부정판단은 무를 직접적으로 발견하는 무화작용에 근거함. 무는 세계에서 직관으로 발견됨.</p><p>대자는 그 자체로 무임 — 즉자에 대한 부정(무화).</p><p><strong>의식의 본성, 의식이 가진 속성</strong></p><ul><li><strong>지향성</strong>: 자신이 아닌 것에 향함, 자신을 벗어남</li><li><strong>욕구</strong>: 자신에게 없는 것을 추구함</li><li><strong>시간성</strong>: 아직 자기가 아닌 것, 주어지지 않은 것으로 나아감</li></ul><h2 id="_4-타자와-시선" tabindex="-1">4. 타자와 시선 <a class="header-anchor" href="#_4-타자와-시선" aria-label="Permalink to &quot;4. 타자와 시선&quot;">​</a></h2><p>타자는 대자를 즉자처럼 만드는 활동(시선)으로 나타남.</p><p><strong>해결 방안과 그 실패</strong></p><ul><li>타자의 시선을 긍정하면서 자신을 즉자로 만듦</li><li>시선을 부정하면서 타자를 즉자로 만듦(무화)</li><li>하지만 둘 다 실패함</li></ul><p>공동체는 근본적으로 대자들의 투쟁을 통해 성립함 — 서로에 대한 부정, 무화.</p><h2 id="_5-자유와-불안" tabindex="-1">5. 자유와 불안 <a class="header-anchor" href="#_5-자유와-불안" aria-label="Permalink to &quot;5. 자유와 불안&quot;">​</a></h2><p><strong>자유</strong>: 대자로서 인간은 언제나 즉자의 질서를 벗어남. 자유는 자신을 선반성적으로 의식하며, 이러한 의식이 곧 불안임. 자유로울 뿐, 무엇이 맞다는 기준은 없음.</p><p><strong>불안</strong>: 자유 자체에 의한 자유의 반성적 파악. 대자는 불안을 피하는 <strong>자기기만</strong>의 방식으로 자신을 의식함.</p><p>대자의 행동을 결정하는 즉자는 없음 — 대자가 즉자에 의미를 부여함. 대자의 행동은 상황에 의해 제약되지만, 상황은 자유를 전제함.</p>',21)])])}const c=l(r,[["render",n]]);export{g as __pageData,c as default};
